       "notes": "CLOCK 1:35–1:55\n\n    SPOKEN: \"Everyone in this room got this email this month. Some of you got it this morning and I'm sorry for reminding you. Personally I hate this emails because clients only send emails when something is wrong and never when it's good\"",
