       "label": "Slide 50",
       "notes": "CLOCK 18:35–19:00\n\n    SPOKEN: \"The frontend is just a window. It's where you talk to the agent and the data. It is not the system. And it's not one thing you have to pick. Engine underneath, windows on top.\"",
