       "notes": "CLOCK 25:30–26:00\n\n    SPOKEN: \"Last steal-this. Where is the why behind your last 50 changes? Or does it live in your head and leave when you do? Make the memory automatic. Every change, human or agent, lands in one place with its why. Just like the database layer: automatic, or it doesn't happen.\"\n\n    CUE: exit line — \"That's six. All chips full. Now let's run that email.\" Hard cut to the payoff.",
