       "key": "68.0.-1",
       "label": "Slide 69",
       "notes": "CLOCK 26:55–30:55 — four full minutes budgeted. The descent is the slide's drama.\n\n    SPOKEN: (walking the layers, one beat each) \"9:00. The email lands, and the first thing that happens is nothing special: it lands in the client's folder, next to everything else we know about them. Database. … The agent picks up the signal. Searches the email history, pulls the client card, pulls performance. Builds the analysis, prepares the change. Backend. … The change goes through the dry run, gets classified: this one's a review-laner. You get the alert. Security. … Your inbox shows the brief, the drafted reply, the prepared change. You read it. You press the button you've now seen three times. Frontend. … Whether you were even allowed to press it was never a question. Code decided that before you saw the card. Auth. … And the change applies, logs itself with its why, and books its own follow-up: check the effect in seven days. Git. … Look up at the clock.\"\n\n    CUE: say the layer name first, THEN fire its fragment — don't race the token.",
