       "notes": "CLOCK 32:00–32:47 (QR line adds ~7s, calibrate at rehearsal)\n\n    SPOKEN: \"Six questions. You answered them with me on the way here, honestly or not. :D And before you panic: only two of them are the foundation. One folder, one skill file. You can build that alone, even inside an agency, just for yourself. Prototype on it, see what crashes. With those two you can test the whole system. Everything else stacks on top, and number three comes before it touches a live account. If you failed most of them: good. That means Monday morning has a job. … And to help you answer those two, I built you a page. Scan this one, pitcocy.com/build. It walks you through the folder and the skill file, and what usually breaks first.\"\n\n    CUE: stack the cards fast, roughly one per second. Advance 7 fires the foundation fragment: rows 4-6 dim, rows 1-2 flip gold, Security picks up the teal tag. Advance 8 reveals the QR corner card (bottom-left) on \"I built you a page\"; point at it. It stays through S69 and S70.",
