       "notes": "On the account level this week was quiet: 86 conversions against 87 the period before, cost up 2,1 percent, every threshold green. This is a real check on Anastasia's insurer account on the tenth of August, and the same run still pulled two things out from underneath those numbers. The second one belongs right next to it: the campaign closest to conversion is now being held back by budget rather than by rank, with share lost to budget at 55,1 percent. And it ends up as a markdown file next to the account files, not in a dashboard nobody opens.",
