       "key": "39",
       "label": "Slide 15 (1/5)",
       "notes": "A large part of our week is calls, and I skipped past that for a long time when I told this story, because it does not look like automation. It is the part clients actually experience. Before every call there is a command, and what comes back is one page: what we promised last time and have not delivered yet, four weeks of trend per campaign with the week a number bends, the change history including everything the client did in the account themselves, and talking points I can copy out of the page. That last one matters more than it sounds, because the thing I used to walk in without was not data, it was the sentence. Two honest notes. This is the one number on the slide I would defend loosely: call prep used to be about an hour for me, an hour and a half with the follow-up, and that is my estimate from working, not a measurement. And the page is in German, so I will translate as I go.",
