       "key": "44",
       "label": "Slide 16 (1/4)",
       "notes": "And then the hour after the call, which is the hour that used to leak. The call is recorded, and out of that recording comes three things. A summary mail as a draft in my Outlook, with an owner on every single line, and it is a draft on purpose, because nothing goes to a client without me reading it. The same call as a dated note in the shared repository, so when Jenny or Anastasia picks that account up they read what happened instead of asking me. And every action item that has our name on it becomes a Trello card for next week, while the client's own items stay in the mail where they belong. The sentence I would take out of this slide is the one at the bottom: a promise I make on a call is a card before I stand up from the table. Everyone in this room has lost one of those.",
