       "key": "49",
       "label": "Slide 18",
       "notes": "This is the first of my five blocks coming back, the one I called new campaigns, and the marker up there says so. What you are looking at is the whole chain the skill runs: it reads the client profile first, which is tone, market, structure and what we agreed never to bid on, then keyword research, then structure, ad groups, negatives, and two ads per ad group with fifteen headlines and four descriptions each. The screenshot is the structure half of a sample build: two campaigns, brand split off, non-brand kept in one pot, and the yellow box is the reasoning the skill writes down for that decision. Consolidating is our default and every split has to earn itself, which is the rule that used to be an opinion. The timing is the next slide, so do not start on the hours here.",
