       "key": "52",
       "label": "Slide 20 (1/5)",
       "notes": "These are my own numbers, not a benchmark. Before we used AI at all we needed eight hours for a complete search campaign setup, with ChatGPT support around six, with the tool we built ourselves three to four, and now with PPC OS and agents it is minutes for the setting up. Two things are doing the work there. The draft comes out this good because it is built along a skill we wrote ourselves, so it is not a generic setup, it is ours. And judging whether it actually holds still takes everything I know about accounts. Somebody in their first year could not make that call in the same time, and that is the part that did not get faster. Only the setting up did, and if I drop that sentence the whole thing is just a claim.",
