       "key": "86",
       "label": "Slide 31 (1/7)",
       "notes": "One thing I owe you here, because everything so far has been my side of it. This is what comes back. The first one is about a reporting page we built to replace a dashboard they had outgrown, and the line I like is the last one, that the explanations help, because a number without a reading is just a number. The second is a colleague at a metrology client who had asked for the English version of a call summary, got it the next morning, and could walk straight into his meeting with it. The third one is my favourite and it is not praise at all: she went through our quality score analysis point by point and wrote back which ones she wants done, and that is what it looks like when an analysis actually gets used. Not one of them has ever asked me which part a machine wrote. They ask whether it is right, and whether it holds up in the room they take it into, and that is exactly the same question they asked me three years ago.",
