       "key": "124",
       "label": "Slide 47",
       "notes": "Two years ago I had never opened a terminal, and slide two of this talk was me being intimidated by it. What I would say to that version of me is the whole sentence, not just the half you can read: 'Give yourself some time, allow yourself to feel intimidated — and then just do it anyway.' The second half is the part that is up there, because that is the part that decides anything. Questions now, and then Miles picks up all the objections I have just left lying around.",
